def log(msg):
    LOGS.mkdir(parents=True, exist_ok=True)
    with open(PERSONALITY_LOG, "a") as f:
        f.write(f"[{datetime.now(datetime.timezone.utc).isoformat()}] {msg}\n")
    print(msg)

### — Savant Insight —
# Purpose: run_quality_scan — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:09:01
def run_quality_scan():
    q_script = BASE / "services/utils/quality_engine.py"
    result = subprocess.run(["python3", str(q_script)], capture_output=True, text=True)
    log(result.stdout)
    report = json.loads((BASE / "logs" / "quality_report.json").read_text())
    avg_score = sum(r["score"] for r in report["results"]) / len(report["results"])
    return avg_score

